output_text:
[
  {
    "id": "no_cart_in_single_file_aisle",
    "text": "Shopping carts are prohibited in single-file shelf aisles where the horizontal passage is only one cell wide.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_push_cart_into_single_file_aisle",
    "text": "An agent must not push a cart from an open aisle into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileShelfAisleWithCart"
    }
  },
  {
    "id": "single_file_items_served_on_foot",
    "text": "Items located in single-file shelf aisles must be interacted with while not holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_at_upper_aisle_mouth",
    "text": "A cart may be set down only at the mouth of a pedestrian-only upper shelf aisle.",
    "abstraction": {
      "state_properties": {
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideOpenAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "upperAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After parking a cart at the mouth of a pedestrian-only aisle, the agent is obliged to retrieve the cart before leaving.",
    "abstraction": {
      "state_properties": {
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtUpperAisleMouth": {
          "pre": {
            "and": [
              "upperAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtUpperAisleMouth",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "no_wandering_without_cart",
    "text": "Except in the entrance/cart bay or during a pedestrian-only aisle excursion, moving around the store without the cart is prohibited.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "entranceCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "allowedOnFootArea": {
          "or": [
            "singleFileShelfAisle",
            "upperAisleMouth",
            "entranceCartBay"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "allowedOnFootArea"
          }
        ]
      }
    }
  },
  {
    "id": "enter_single_file_only_to_shop",
    "text": "If an agent enters a pedestrian-only shelf aisle on foot, they are obliged to interact with a shelf in that aisle before returning to the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisleOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileShelfAisleOnFoot",
      "discharge": {
        "and": [
          "singleFileShelfAisle",
          {
            "not": "hasCart"
          },
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "return_to_cart_after_single_file_item",
    "text": "After interacting with an item in a pedestrian-only shelf aisle, the agent must return to the aisle mouth and pick the cart back up.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "singleFileItemInteractionOnFoot": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        },
        "retrieveCartAtUpperAisleMouth": {
          "pre": {
            "and": [
              "upperAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "singleFileItemInteractionOnFoot",
      "discharge": "retrieveCartAtUpperAisleMouth"
    }
  }
]
